"""Exercise the legacy HTTP routes in dependency order against isolated fixtures."""
import os
import json
from pathlib import Path
import sqlite3
import time

def run(harness):
    ROOT, HOME, PROJECT = harness.ROOT, harness.HOME, harness.PROJECT
    app = harness.app
    call, request = harness.call, harness.request
    wait_idle, stream = harness.wait_idle, harness.stream
    events_stop, events_conn = harness.events_stop, harness.events_conn
    call("health", "GET", "health", auth=False)
    request("bad-host", "GET", "/api/health", auth=False, headers={"Host": "evil.example:80"})
    call("missing-token", "GET", "state", auth=False)
    call("wrong-token", "GET", "state", headers={"X-Antiquota-Token": "wrong"})
    call("events-wrong-token", "GET", "events?token=wrong")
    request("unknown-static", "GET", "/unknown", auth=False)
    request("static-index", "GET", "/", auth=False)
    request("static-js", "GET", "/app.js", auth=False)
    request("static-css", "GET", "/app.css", auth=False)
    for path in sorted((ROOT / "antiquota/ui/vendor").glob("*")):
        if path.suffix in (".js", ".css"):
            request("static-vendor-" + path.name.replace(".", "-"), "GET", "/vendor/" + path.name, auth=False)
    request("vendor-traversal", "GET", "/vendor/../app.js", auth=False)
    call("state-initial", "GET", "state")
    call("engine", "GET", "engine")
    call("engine-log", "GET", "engine/log")
    call("accounts-initial", "GET", "accounts")
    call("accounts-probe", "POST", "accounts/probe", {})
    call("account-check", "POST", "accounts/one@example.com/check", {})
    time.sleep(0.7)
    call("account-check-idle", "POST", "accounts/one@example.com/check", {})
    call("account-pause", "POST", "accounts/one@example.com/pause", {"on": True})
    call("account-resume", "POST", "accounts/one@example.com/pause", {"on": False})
    call("account-missing-check", "POST", "accounts/missing@example.com/check", {})
    call("usage-empty", "GET", "usage?days=3")
    call("routing", "GET", "routing?n=60")
    call("filesystem", "GET", "fs")
    call("filesystem-outside", "GET", "fs?path=/etc")
    call("settings", "GET", "settings")
    harness.capture_stack("stack-plugin-config.json", "config/config.json", "after settings")
    harness.capture_stack("stack-plugin-readme.md", "config/plugins/example/README.md", "after settings")
    harness.capture_stack("stack-gemini.md", "GEMINI.md", "after settings")
    call("defaults", "PUT", "settings/defaults", {"model": "gemini-3.8-flash-high", "reserve": 4, "keep_awake": "off"})
    call("defaults-error", "PUT", "settings/defaults", {"reserve": 51})
    call("settings-file-missing", "GET", "settings/file?path=config/new.json")
    call("settings-file-put", "PUT", "settings/file", {"path": "config/new.json", "text": '{"enabled":true}\n'})
    call("settings-file-read", "GET", "settings/file?path=config/new.json")
    call("settings-file-invalid", "PUT", "settings/file", {"path": "config/new.json", "text": "{"})
    call("settings-file-private", "GET", "settings/file?path=antigravity-cli/conversations/example.db")
    call("settings-hook-put", "PUT", "settings/hook/example", {"value": {"enabled": True, "Stop": []}})
    call("settings-hook-get", "GET", "settings/hook/example")
    call("settings-hook-disable", "POST", "settings/hook/example/enabled", {"on": False})
    harness.capture_stack("stack-hooks.json", "config/hooks.json", "after settings-hook-disable, before deletion")
    call("settings-hook-delete", "DELETE", "settings/hook/example")
    call("settings-mcp-put", "PUT", "settings/mcp/example", {"value": {"command": "fixture-server", "args": []}})
    call("settings-mcp-get", "GET", "settings/mcp/example")
    harness.capture_stack("stack-mcp.json", "config/mcp_config.json", "after settings-mcp-get, before deletion")
    call("settings-mcp-disable", "POST", "settings/mcp/example/enabled", {"on": False})
    call("settings-mcp-delete", "DELETE", "settings/mcp/example")
    call("settings-copy-rule", "POST", "settings/copy", {"source": "cli", "kind": "rule", "name": "example.md"})
    call("settings-copy-skill", "POST", "settings/copy", {"source": "cli", "kind": "skill", "name": "example"})
    harness.capture_stack("stack-rule.md", "config/rules/example.md", "after settings-copy-rule, before deletion")
    harness.capture_stack("stack-skill.md", "config/skills/example/SKILL.md", "after settings-copy-skill, before deletion")
    call("settings-delete-rule", "DELETE", "settings/rule/example.md")
    call("settings-delete-skill", "DELETE", "settings/skill/example")
    call("settings-kind-error", "GET", "settings/invalid/example")
    call("permissions", "GET", "permissions")
    call("permissions-put", "PUT", "permissions", {"allow": ["command(ls)", "command(ls)", "command(git status)"], "deny": ["command(rm)"]})
    harness.capture_stack("stack-permissions.json", "antigravity-cli/settings.json", "after permissions-put, before reseed")
    call("permissions-error", "PUT", "permissions", {"allow": [42]})
    call("stack", "GET", "stack?refresh=1")
    call("stack-reseed", "POST", "stack/reseed", {})
    call("body-limit", "POST", "sessions", raw=b"", declared_size=5000001)
    call("invalid-json", "POST", "sessions", raw=b"{", headers={"Content-Type": "application/json"})
    meta = call("session-create", "POST", "sessions", {"cwd": str(PROJECT), "title": "Contract fixture", "model": "gemini-3.8-flash-high"})
    sid = meta["id"]
    prefix = "sessions/" + sid
    call("session-get-empty", "GET", prefix)
    call("session-patch", "PATCH", prefix, {"title": "Contract renamed", "mode": "accept-edits", "effort": "high", "pinned": True, "archived": False})
    call("session-patch-invalid", "PATCH", prefix, {"mode": "invalid"})
    call("session-missing", "GET", "sessions/missing")
    call("session-create-invalid", "POST", "sessions", {"cwd": str(HOME / "missing")})
    call("send-empty", "POST", prefix + "/send", {"text": " "})
    call("attachment-upload", "POST", prefix + "/attach", raw=b"Fixture attachment.\n", headers={"X-Filename": "contract%20note.txt"})
    call("attachment-download", "GET", prefix + "/attachments/contract%20note.txt?token=" + app.token)
    call("attachment-download-header-only", "GET", prefix + "/attachments/contract%20note.txt")
    call("attachment-download-missing", "GET", prefix + "/attachments/missing.txt?token=" + app.token)
    call("attachment-upload-plain", "POST", prefix + "/attach", raw=b"Plain fixture attachment.\n", headers={"X-Filename": "fixture.txt"})
    call("attachment-download-plain", "GET", prefix + "/attachments/fixture.txt?token=" + app.token)
    call("attachment-limit", "POST", prefix + "/attach", raw=b"", declared_size=25000001)
    call("send", "POST", prefix + "/send", {"text": "Hello contract fixture."})
    wait_idle(sid)
    checkpoint = Path(harness.BASE) / "sessions" / sid / "checkpoints/1.json"
    harness.captured_disk["session-checkpoint.json"] = json.loads(checkpoint.read_text())
    call("session-get-turn", "GET", prefix)
    call("search", "GET", "search?q=contract")
    call("search-short", "GET", "search?q=c")
    call("session-state", "GET", prefix + "/state")
    call("session-file", "GET", prefix + "/file?path=notes.txt")
    call("session-file-outside", "GET", prefix + "/file?path=/etc/passwd")
    call("session-files", "GET", prefix + "/files?q=note")
    call("session-tree", "GET", prefix + "/tree")
    call("session-tree-outside", "GET", prefix + "/tree?path=../../")
    call("session-note", "POST", prefix + "/note", {"text": "Keep the fixture isolated."})
    call("session-note-empty", "POST", prefix + "/note", {"text": ""})
    call("session-shell", "POST", prefix + "/shell", {"cmd": "printf 'fixture shell\\n'"})
    call("session-shell-empty", "POST", prefix + "/shell", {"cmd": ""})
    call("session-compact", "POST", prefix + "/compact", {})
    fork = call("session-fork", "POST", prefix + "/fork", {})
    fid = fork["id"]
    call("session-inherit", "POST", "sessions/" + fid + "/inherit", {"from": sid})
    call("session-inherit-error", "POST", prefix + "/inherit", {"from": "missing"})
    call("session-rewind", "POST", prefix + "/rewind", {"turn": 1})
    call("session-rewind-empty", "POST", prefix + "/rewind", {"turn": 1})
    call("session-clear", "POST", prefix + "/clear", {})
    os.environ["STUB_SLEEP"] = "1.5"
    call("send-long", "POST", prefix + "/send", {"text": "Work briefly."})
    call("send-queued", "POST", prefix + "/send", {"text": "Steer this turn."})
    call("session-steer", "POST", prefix + "/steer", {})
    wait_idle(sid)
    del os.environ["STUB_SLEEP"]
    call("session-patch-default", "PATCH", prefix, {"mode": "default"})
    pending = call("approval-request", "POST", "approvals", {"session": sid, "tool": "run_command", "args": {"CommandLine": "touch approval-file"}})
    aid = pending["pending"]
    call("approval-wait", "GET", "approvals/" + aid + "?wait=0")
    call("approval-answer-invalid", "POST", "approvals/" + aid + "/answer", {"decision": "maybe"})
    call("approval-answer", "POST", "approvals/" + aid + "/answer", {"decision": "deny", "why": "fixture denied"})
    call("approval-read-decided", "GET", "approvals/" + aid + "?wait=0")
    allowed = call("approval-request-allow", "POST", "approvals", {"session": sid, "tool": "run_command", "args": {"CommandLine": "touch allowed-file"}})
    call("approval-answer-allow", "POST", "approvals/" + allowed["pending"] + "/answer", {"decision": "allow", "always": False})
    call("approval-read-allowed", "GET", "approvals/" + allowed["pending"] + "?wait=0")
    call("approval-unknown", "GET", "approvals/missing?wait=0")
    call("approval-unknown-session", "POST", "approvals", {"session": "missing", "tool": "run_command", "args": {"CommandLine": "ls"}})
    call("approval-immediate-read", "POST", "approvals", {"session": sid, "tool": "read_file", "args": {"TargetFile": "readme.txt"}})
    call("session-stop", "POST", prefix + "/stop", {})
    job = call("job-create", "POST", prefix + "/jobs", {"cmd": "printf 'fixture job\\n'; sleep 5", "every": "90s", "notify": False})
    jid = job["id"]
    time.sleep(0.1)
    call("job-log", "GET", prefix + "/jobs/" + jid + "/log")
    call("job-stop", "POST", prefix + "/jobs/" + jid + "/stop", {})
    call("job-empty", "POST", prefix + "/jobs", {"cmd": ""})
    call("loop-create", "POST", prefix + "/loop", {"every": "15m", "prompt": "Loop fixture."})
    call("loop-delete", "DELETE", prefix + "/loop")
    call("schedule-create", "POST", prefix + "/loop", {"at": "23:59", "prompt": "Daily fixture."})
    call("schedule-delete", "DELETE", prefix + "/loop")
    call("schedule-invalid", "POST", prefix + "/loop", {"at": "25:00"})
    call("loop-invalid", "POST", prefix + "/loop", {"every": "invalid"})
    call("goal-create", "POST", prefix + "/goal", {"objective": "Complete fixture.", "check": "test -f notes.txt", "verifier": True, "verifier_model": "gemini-3.8-flash-high", "max_rounds": 2})
    wait_idle(sid)
    call("goal-get-met", "GET", prefix)
    call("goal-resume", "POST", prefix + "/goal/resume", {})
    wait_idle(sid)
    call("goal-delete", "DELETE", prefix + "/goal")
    call("goal-resume-empty", "POST", prefix + "/goal/resume", {})
    call("goal-empty", "POST", prefix + "/goal", {"objective": ""})
    call("terminal-create", "POST", prefix + "/term", {"cols": 80, "rows": 24})
    tc, ts, tt, tr = stream("terminal-sse", "/api/" + prefix + "/term/stream?token=" + app.token)
    time.sleep(0.15)
    call("terminal-input", "POST", prefix + "/term/input", {"data": "printf 'contract-terminal\\n'\r"})
    call("terminal-resize", "POST", prefix + "/term/resize", {"cols": 120, "rows": 40})
    time.sleep(0.25)
    call("terminal-kill", "POST", prefix + "/term/kill", {})
    tt.join(2)
    ts.set(); tc.close()
    call("terminal-input-missing", "POST", prefix + "/term/input", {"data": "a"})
    call("terminal-stream-missing", "GET", prefix + "/term/stream?token=" + app.token)
    call("terminal-restart", "POST", prefix + "/term", {"restart": True})
    call("terminal-kill-again", "POST", prefix + "/term/kill", {})
    call("transcribe", "POST", "transcribe", raw=b"RIFFfixture-audio", headers={"X-Audio-Type": "wav"})
    os.environ["STUB_DICTATION"] = "NO_SPEECH"
    call("transcribe-no-speech", "POST", "transcribe", raw=b"RIFFfixture-silence", headers={"X-Audio-Type": "wav"})
    call("transcribe-empty", "POST", "transcribe", raw=b"")
    call("transcribe-limit", "POST", "transcribe", raw=b"", declared_size=25000001)
    call("session-git", "GET", prefix + "/git")
    call("session-git-diff", "GET", prefix + "/git/diff?path=notes.txt")
    call("session-git-discard", "POST", prefix + "/git/discard", {"path": "notes.txt"})
    call("session-git-commit", "POST", prefix + "/git/commit", {"message": "Commit fixture files"})
    call("session-git-merge-no-worktree", "POST", prefix + "/git/merge", {})
    call("session-git-remove-no-worktree", "POST", prefix + "/git/remove", {})
    wt = call("worktree-create", "POST", "sessions", {"cwd": str(PROJECT), "title": "Worktree fixture", "worktree": True})
    wid = wt["id"]
    (Path(wt["cwd"]) / "worktree.txt").write_text("Worktree change.\n")
    call("worktree-git", "GET", "sessions/" + wid + "/git")
    call("worktree-commit", "POST", "sessions/" + wid + "/git/commit", {"message": "Add worktree fixture"})
    call("worktree-committed-diff", "GET", "sessions/" + wid + "/git/diff?committed=1")
    call("worktree-merge", "POST", "sessions/" + wid + "/git/merge", {})
    call("worktree-remove", "POST", "sessions/" + wid + "/git/remove", {"delete_branch": True})
    conv = app.engine.sessions[sid].meta["conversation_id"]
    database = Path(harness.BASE) / "stack/.gemini/antigravity-cli/conversations" / (conv + ".db")
    thinking = b"Check the isolated fixture."
    planner = bytes([26, len(thinking)]) + thinking
    payload = bytes([162, 1, len(planner)]) + planner
    with sqlite3.connect(database) as con:
        con.execute("create table steps (idx integer, step_type integer, step_payload blob)")
        con.execute("insert into steps values (4, 15, ?)", (payload,))
    call("thinking-send", "POST", prefix + "/send", {"text": "Show the captured thinking."})
    wait_idle(sid)
    call("thinking-session", "GET", prefix)
    os.environ["STUB_429"] = app.engine.sessions[sid].meta["last_slot"]
    call("quota-handoff-send", "POST", prefix + "/send", {"text": "Continue after a quota wall."})
    wait_idle(sid)
    del os.environ["STUB_429"]
    call("quota-handoff-session", "GET", prefix)
    call("account-pause-one-for-wall", "POST", "accounts/one@example.com/pause", {"on": True})
    call("account-pause-two-for-wall", "POST", "accounts/two@example.com/pause", {"on": True})
    call("all-paused-send", "POST", prefix + "/send", {"text": "Report paused accounts."})
    wait_idle(sid)
    call("all-paused-session", "GET", prefix)
    call("account-resume-one-after-wall", "POST", "accounts/one@example.com/pause", {"on": False})
    call("account-resume-two-after-wall", "POST", "accounts/two@example.com/pause", {"on": False})
    os.environ["STUB_EMAIL"] = "three@example.com"
    lg = call("login-start", "POST", "accounts/login", {})
    lid = lg["id"]
    call("login-poll", "GET", "accounts/login/" + lid)
    call("login-code-invalid", "POST", "accounts/login/" + lid, {"code": "a\nb"})
    call("login-submit", "POST", "accounts/login/" + lid, {"code": "good-code"})
    call("login-delete", "DELETE", "accounts/login/" + lid)
    call("login-poll-replaced", "GET", "accounts/login/" + lid)
    call("login-submit-replaced", "POST", "accounts/login/" + lid, {"code": "good-code"})
    call("account-delete", "DELETE", "accounts/three@example.com")
    call("account-delete-invalid", "DELETE", "accounts/..")
    call("usage-after-turns", "GET", "usage?days=3")
    call("state-final", "GET", "state")
    call("session-delete", "DELETE", "sessions/" + fid)
    call("unknown-route", "GET", "unknown")
    time.sleep(0.2)
    events_stop.set()
    events_conn.close()
    call("shutdown", "POST", "shutdown", {})
